  /* Update only live indicators: never replaces camera, player, buttons or focused inputs.
   * level is an optional actual RMS scalar (0..1); absent/unavailable values show no bars. */
  function updateLive(input={},doc){const d=doc||(typeof document!=='undefined'?document:null);if(!d?.getElementById)return;const m=model(input),clock=d.getElementById('recorder-elapsed'),live=d.getElementById('recorder-live-state'),meter=d.getElementById('recorder-meter'),fill=d.getElementById('recorder-meter-fill'),caption=d.getElementById('recorder-meter-caption'),section=d.querySelector?.('.recording-center');if(clock)clock.textContent=m.elapsed;if(live){const label=live.querySelector?.('span:last-child');if(label&&label.textContent!==m.status)label.textContent=m.status;}if(section)section.dataset.recorderPhase=m.phase;const available=m.live&&Number.isFinite(input.level)&&input.level>=0&&!m.loop;const level=available?Math.round(Math.max(0,Math.min(1,input.level))*100):0;if(meter){meter.setAttribute('aria-valuenow',String(level));meter.setAttribute('aria-valuetext',available?level+'%':m.c.meterIdle);meter.dataset.available=String(available);}if(fill)fill.style.width=level+'%';if(caption)caption.textContent=available?(m.source==='synth'&&m.mode!=='video'?m.c.meterSynth:m.c.meter):(m.live&&m.mode==='video'?m.c.meterVideo:m.c.meterIdle);}
